def l2_working_set_pressure(p, hw, cfg) -> float:
    """Saturating pressure from the GEMM operand and output footprint relative to L2."""
    working_set = (p.M * p.K + p.K * p.N + p.M * p.N) * p.bytes_per_element
    return working_set / max(working_set + hw.l2_bytes, 1e-9)

def parallel_reduction_traffic_fraction(p, hw, cfg) -> float:
    """Fraction of output-equivalent traffic spent moving parallel split-K partials."""
    if cfg.split_k_mode != "parallel":
        return 0.0
    base = max(p.bytes_per_element, 1e-9)
    partial = 2.0 * max(1, cfg.split_k) * p.acc_bytes_per_element
    return partial / (base + partial)

def serial_reduction_dependency(p, hw, cfg) -> float:
    """Fraction of K-loop opportunities occupied by serial split-K boundaries.

    Serial split-K must accumulate successive partial slices in order, exposing
    a dependency that prevents those slice computations from being independent.
    """
    if cfg.split_k_mode != "serial":
        return 0.0
    iters = max(1, math.ceil(p.K / max(1, cfg.tile_k)))
    return min(1.0, max(0, cfg.split_k - 1) / iters)

def instruction_density(p, hw, cfg) -> float:
    """Static SASS instructions per useful multiply-add FLOP in one CTA tile.
    Larger values mean more instruction overhead per unit of GEMM work.
    """
    useful_flops = 2.0 * cfg.tile_m * cfg.tile_n * max(1, p.K)
    return cfg.inst_total / max(1e-9, useful_flops)

def register_file_pressure(p, hw, cfg) -> float:
    """Fraction of an SM register file consumed by one CTA; larger is worse."""
    return (cfg.regs_per_thread * cfg.threads) / max(1.0, hw.regs_per_sm)

def thread_work_granularity_deficit(p, hw, cfg) -> float:
    """Fractional CTA-thread overhead relative to its output-element work. Larger is worse."""
    outputs = max(1.0, float(cfg.tile_m) * float(cfg.tile_n))
    return cfg.threads / max(1e-9, cfg.threads + outputs)

def tile_roofline_deficit(p, hw, cfg) -> float:
    """Deficit of a CTA tile's arithmetic intensity relative to the hardware roofline; larger is worse."""
    flops = 2.0 * cfg.tile_m * cfg.tile_n * cfg.tile_k
    operand_bytes = (cfg.tile_m * cfg.tile_k + cfg.tile_k * cfg.tile_n) * p.bytes_per_element
    intensity = flops / max(operand_bytes, 1e-9)
    return max(0.0, 1.0 - intensity / max(hw.ridge_point, 1e-9))

def parallel_reduction_compute_fraction(p, hw, cfg) -> float:
    """Extra accumulator additions caused by parallel split-K, relative to GEMM FLOPs.
    Each output element needs split_k - 1 partial-sum additions after partial kernels finish;
    this is extra arithmetic, distinct from the global-memory traffic of the reduction.
    """
    if cfg.split_k_mode != "parallel":
        return 0.0
    return max(0.0, cfg.split_k - 1.0) / max(1.0, 2.0 * p.K)

def mainloop_iteration_count(p, hw, cfg) -> float:
    """Number of K-slices executed by one CTA's mainloop.

    Each slice introduces loop-control and producer/consumer synchronization work;
    more slices therefore expose more fixed per-iteration latency.  The ceiling
    includes the final, possibly partial, K slice.
    """
    return float(math.ceil(p.K / max(1, cfg.tile_k)))

def tm_cta_warps(p, hw, cfg) -> float:
    """log2 of warps in one CTA barrier domain. Larger is worse."""
    return math.log2(max(1.0, cfg.threads / 32.0))

def tm_regstaged(p, hw, cfg) -> float:
    """1 for the register-staged two-stage mainloop (one iteration of compute covers each global load), else 0."""
    return 1.0 if cfg.stages <= 2 else 0.0

def tm_log_inst(p, hw, cfg) -> float:
    """log2 of the static SASS instruction count (code footprint)."""
    return math.log2(max(1.0, float(cfg.inst_total)))

def splitk_sm_latency_rounds_log(p, hw, cfg) -> float:
    """log2 of the memory round trips the busiest SM must serialise: its n=ceil(tiles*sk/SMs) CTAs stream n*ceil(K/(tk*sk)) k-steps, while only min(n, blocks/SM)*(stages-1) k-step loads can be in flight at once (Little's law). Larger is worse."""
    s = max(1, cfg.split_k); T = math.ceil(p.M / cfg.tile_m) * math.ceil(p.N / cfg.tile_n); n = math.ceil(T * s / hw.sm_count)
    steps = n * math.ceil(p.K / (cfg.tile_k * s))
    inflight = min(n, max(1, cfg.max_blocks_per_sm)) * max(1, cfg.stages - 1)
    return math.log2(max(1.0, steps / inflight))
